function paint(h){return !h||h==='none'?[]:[{type:'SOLID',color:{r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255}}];}
async function main(){
 for(const style of ['Regular','Semi Bold'])await figma.loadFontAsync({family:'Inter',style});
 const frames=[];
 for(let i=0;i<screens.length;i++){
  const s=screens[i],f=figma.createFrame();f.name=s.name;f.resize(1440,960);f.x=(i%4)*1520;f.y=Math.floor(i/4)*1040;f.fills=paint('#F3F6F5');frames.push(f);const groups={};
  for(const d of s.items){let n;
   if(d.type==='rect'){n=figma.createRectangle();n.resize(d.w,d.h);n.cornerRadius=d.r;n.fills=paint(d.fill);n.strokes=paint(d.stroke);n.strokeWeight=1;n.opacity=d.opacity;}
   else if(d.type==='text'){n=figma.createText();n.fontName={family:'Inter',style:d.bold?'Semi Bold':'Regular'};n.fontSize=d.size;n.characters=d.text;n.fills=paint(d.fill);}
   else{n=figma.createLine();n.resize(Math.max(.01,Math.hypot(d.x2-d.x,d.y2-d.y)),0);n.rotation=-Math.atan2(d.y2-d.y,d.x2-d.x)*180/Math.PI;n.strokes=paint(d.fill);n.strokeWeight=d.sw;}
   f.appendChild(n);n.name=d.name;n.x=d.x;n.y=d.y;(groups[d.group]??=[]).push(n);
  }
  for(const[name,nodes]of Object.entries(groups))if(name!=='Background'&&nodes.length)figma.group(nodes,f).name=name;
 }
 figma.currentPage.selection=frames;figma.viewport.scrollAndZoomIntoView(frames);figma.closePlugin('Đã tạo 24 màn Web Admin SaaS. Có thể sửa chữ, màu và từng thành phần.');
}
main().catch(e=>figma.closePlugin('Lỗi: '+e.message));
